  try {
    JSON.parse(input);
    console.log("Valid JSON");
    process.exit(0);
  } catch (error) {
    const message = error instanceof SyntaxError ? error.message : "Unknown error";
    console.log(`Invalid JSON: ${message}`);
    process.exit(1);
  }
}

main();

