        "new_string": "/**\n * Add two numbers.\n */\nexport function add(a: number, b: number): number {\n  return a + b;\n}\n\n/**\n * Greet someone with a time-of-day aware message.\n *\n * Returns a greeting that varies based on the current time:\n * - Morning (5:00 - 11:59): \"Good morning, {name}!\"\n * - Afternoon (12:00 - 16:59): \"Good afternoon, {name}!\"\n * - Evening (17:00 - 20:59): \"Good evening, {name}!\"\n * - Night (21:00 - 4:59): \"Good night, {name}!\"\n *\n * @param name - The name of the person to greet\n * @param date - Optional date to use for determining time of day (defaults to current time)\n * @returns A time-appropriate greeting message\n *\n * @example\n * // Using current time\n * greetWithTime(\"Alice\");\n * // => \"Good morning, Alice!\" (if called in the morning)\n *\n * @example\n * // Using a specific time\n * greetWithTime(\"Bob\", new Date(\"2026-01-15T14:30:00\"));\n * // => \"Good afternoon, Bob!\"\n */\nexport function greetWithTime(name: string, date: Date = new Date()): string {\n  const hour = date.getHours();\n\n  let timeOfDay: string;\n  if (hour >= 5 && hour < 12) {\n    timeOfDay = \"morning\";\n  } else if (hour >= 12 && hour < 17) {\n    timeOfDay = \"afternoon\";\n  } else if (hour >= 17 && hour < 21) {\n    timeOfDay = \"evening\";\n  } else {\n    timeOfDay = \"night\";\n  }\n\n  return `Good ${timeOfDay}, ${name}!`;\n}"
