        "file_path": "/private/tmp/rp1-evals/d6eae186/workspace/scripts/validate-json.py",
        "content": "#!/usr/bin/env python3\n\"\"\"\nUltra-performant JSON Validation Script\n\nA high-performance JSON validation tool that supports:\n- Streaming/iterative parsing for memory-efficient handling of large files\n- Optional JSON Schema validation\n- Early-exit on first error (default) or full-scan mode\n- Clear error messages with line numbers and context\n\nUsage Examples:\n    # Basic syntax validation\n    python validate-json.py data.json\n\n    # Validate from stdin\n    cat data.json | python validate-json.py -\n\n    # With JSON Schema validation\n    python validate-json.py data.json --schema schema.json\n\n    # Full scan mode (report all errors)\n    python validate-json.py data.json --full-scan\n\n    # Show timing/benchmark information\n    python validate-json.py data.json --timing\n\n    # Output as JSON\n    python validate-json.py data.json --output json\n\nDependencies:\n    pip install ijson jsonschema\n\nPerformance Notes:\n    - Uses ijson for streaming large JSON files without loading entire file into memory\n    - Early exit on first validation error by default for maximum performance\n    - Progress indicator shown for files larger than 1MB\n\"\"\"\n\nimport argparse\nimport json\nimport sys\nimport time\nfrom pathlib import Path\nfrom typing import TextIO\n\n\ndef create_parser() -> argparse.ArgumentParser:\n    \"\"\"Create and return the argument parser with all CLI options.\"\"\"\n    parser = argparse.ArgumentParser(\n        prog=\"validate-json\",\n        description=\"Ultra-performant JSON validation with streaming support\",\n        epilog=\"Examples:\\n\"\n        \"  %(prog)s data.json                    # Basic validation\\n\"\n        \"  %(prog)s data.json --schema s.json    # With schema\\n\"\n        \"  %(prog)s - < data.json                # From stdin\\n\"\n        \"  %(prog)s data.json --full-scan        # Report all errors\\n\",\n        formatter_class=argparse.RawDescriptionHelpFormatter,\n    )\n\n    parser.add_argument(\n        \"file\",\n        type=str,\n        help=\"JSON file to validate (use '-' for stdin)\",\n    )\n\n    parser.add_argument(\n        \"--schema\",\n        \"-s\",\n        type=str,\n        metavar=\"PATH\",\n        help=\"JSON Schema file for validation\",\n    )\n\n    parser.add_argument(\n        \"--output\",\n        \"-o\",\n        choices=[\"text\", \"json\"],\n        default=\"text\",\n        help=\"Output format (default: text)\",\n    )\n\n    parser.add_argument(\n        \"--full-scan\",\n        \"-f\",\n        action=\"store_true\",\n        help=\"Report all errors instead of exiting on first error\",\n    )\n\n    parser.add_argument(\n        \"--timing\",\n        \"-t\",\n        action=\"store_true\",\n        help=\"Show timing/benchmark information\",\n    )\n\n    parser.add_argument(\n        \"--quiet\",\n        \"-q\",\n        action=\"store_true\",\n        help=\"Suppress output on success, only show errors\",\n    )\n\n    parser.add_argument(\n        \"--no-progress\",\n        action=\"store_true\",\n        help=\"Disable progress indicator for large files\",\n    )\n\n    return parser\n\n\nclass ValidationError:\n    \"\"\"Represents a validation error with context.\"\"\"\n\n    def __init__(\n        self,\n        message: str,\n        line: int | None = None,\n        column: int | None = None,\n        path: str | None = None,\n        context: str | None = None,\n    ):\n        self.message = message\n        self.line = line\n        self.column = column\n        self.path = path\n        self.context = context\n\n    def to_dict(self) -> dict:\n        \"\"\"Convert error to dictionary for JSON output.\"\"\"\n        result = {\"message\": self.message}\n        if self.line is not None:\n            result[\"line\"] = self.line\n        if self.column is not None:\n            result[\"column\"] = self.column\n        if self.path is not None:\n            result[\"path\"] = self.path\n        if self.context is not None:\n            result[\"context\"] = self.context\n        return result\n\n    def to_text(self) -> str:\n        \"\"\"Format error as human-readable text.\"\"\"\n        parts = []\n        if self.line is not None:\n            loc = f\"line {self.line}\"\n            if self.column is not None:\n                loc += f\", column {self.column}\"\n            parts.append(f\"[{loc}]\")\n        if self.path:\n            parts.append(f\"at '{self.path}'\")\n        parts.append(self.message)\n        result = \" \".join(parts)\n        if self.context:\n            result += f\"\\n  Context: {self.context}\"\n        return result\n\n\nclass ValidationResult:\n    \"\"\"Holds the complete validation result.\"\"\"\n\n    def __init__(self):\n        self.valid = True\n        self.errors: list[ValidationError] = []\n        self.file_size: int | None = None\n        self.elapsed_time: float | None = None\n\n    def add_error(self, error: ValidationError):\n        \"\"\"Add an error to the result.\"\"\"\n        self.valid = False\n        self.errors.append(error)\n\n    def to_dict(self) -> dict:\n        \"\"\"Convert result to dictionary for JSON output.\"\"\"\n        result = {\n            \"valid\": self.valid,\n            \"errors\": [e.to_dict() for e in self.errors],\n            \"error_count\": len(self.errors),\n        }\n        if self.file_size is not None:\n            result[\"file_size_bytes\"] = self.file_size\n        if self.elapsed_time is not None:\n            result[\"elapsed_seconds\"] = round(self.elapsed_time, 4)\n        return result\n\n\ndef get_line_col_from_position(content: str, pos: int) -> tuple[int, int]:\n    \"\"\"Calculate line and column number from character position.\"\"\"\n    if pos < 0 or pos > len(content):\n        return 1, 1\n    lines = content[:pos].split(\"\\n\")\n    line = len(lines)\n    col = len(lines[-1]) + 1\n    return line, col\n\n\ndef get_context_around_position(content: str, pos: int, context_chars: int = 30) -> str:\n    \"\"\"Get a snippet of content around the error position.\"\"\"\n    start = max(0, pos - context_chars)\n    end = min(len(content), pos + context_chars)\n    snippet = content[start:end]\n    snippet = snippet.replace(\"\\n\", \"\\\\n\").replace(\"\\t\", \"\\\\t\")\n    if start > 0:\n        snippet = \"...\" + snippet\n    if end < len(content):\n        snippet = snippet + \"...\"\n    return snippet\n\n\ndef validate_json_syntax_streaming(\n    file_path: str | None,\n    file_obj: TextIO | None,\n    result: ValidationResult,\n    early_exit: bool = True,\n    show_progress: bool = True,\n) -> bool:\n    \"\"\"\n    Validate JSON syntax using streaming parser (ijson) for memory efficiency.\n\n    Args:\n        file_path: Path to the JSON file (None if using stdin)\n        file_obj: File object to read from (for stdin)\n        result: ValidationResult to populate\n        early_exit: If True, stop on first error\n        show_progress: If True, show progress for large files\n\n    Returns:\n        True if syntax is valid, False otherwise\n    \"\"\"\n    try:\n        import ijson\n    except ImportError:\n        result.add_error(\n            ValidationError(\n                \"ijson library not installed. Install with: pip install ijson\"\n            )\n        )\n        return False\n\n    content = None\n    file_size = 0\n\n    try:\n        if file_path:\n            file_size = Path(file_path).stat().st_size\n            result.file_size = file_size\n            with open(file_path, \"rb\") as f:\n                content_bytes = f.read()\n                content = content_bytes.decode(\"utf-8\")\n        elif file_obj:\n            content = file_obj.read()\n            content_bytes = content.encode(\"utf-8\")\n            file_size = len(content_bytes)\n            result.file_size = file_size\n\n        if not content or not content.strip():\n            result.add_error(ValidationError(\"Empty or whitespace-only JSON input\"))\n            return False\n\n        show_progress = show_progress and file_size > 1_000_000\n\n        if show_progress:\n            sys.stderr.write(\n                f\"Validating {file_size / 1_000_000:.1f}MB file (streaming)...\\n\"\n            )\n\n        from io import BytesIO\n\n        stream = BytesIO(content_bytes)\n\n        try:\n            event_count = 0\n            for prefix, event, value in ijson.parse(stream, use_float=True):\n                event_count += 1\n                if show_progress and event_count % 100000 == 0:\n                    pos = stream.tell()\n                    pct = (pos / file_size) * 100\n                    sys.stderr.write(f\"\\rProgress: {pct:.1f}%\")\n                    sys.stderr.flush()\n\n            if show_progress:\n                sys.stderr.write(\"\\r\" + \" \" * 40 + \"\\r\")\n                sys.stderr.flush()\n\n            return True\n\n        except ijson.JSONError as e:\n            error_msg = str(e)\n            line, col = 1, 1\n            context = None\n\n            if hasattr(e, \"pos\") and e.pos is not None:\n                line, col = get_line_col_from_position(content, e.pos)\n                context = get_context_around_position(content, e.pos)\n            else:\n                import re\n\n                pos_match = re.search(r\"position (\\d+)\", error_msg)\n                if pos_match:\n                    pos = int(pos_match.group(1))\n                    line, col = get_line_col_from_position(content, pos)\n                    context = get_context_around_position(content, pos)\n\n            result.add_error(\n                ValidationError(\n                    message=f\"JSON syntax error: {error_msg}\",\n                    line=line,\n                    column=col,\n                    context=context,\n                )\n            )\n            return False\n\n    except FileNotFoundError:\n        result.add_error(ValidationError(f\"File not found: {file_path}\"))\n        return False\n    except PermissionError:\n        result.add_error(ValidationError(f\"Permission denied: {file_path}\"))\n        return False\n    except UnicodeDecodeError as e:\n        result.add_error(\n            ValidationError(f\"Invalid UTF-8 encoding: {e}\")\n        )\n        return False\n    except Exception as e:\n        result.add_error(ValidationError(f\"Unexpected error during parsing: {e}\"))\n        return False\n\n\ndef validate_json_schema(\n    file_path: str | None,\n    file_obj: TextIO | None,\n    schema_path: str,\n    result: ValidationResult,\n    early_exit: bool = True,\n) -> bool:\n    \"\"\"\n    Validate JSON against a JSON Schema.\n\n    Args:\n        file_path: Path to the JSON file\n        file_obj: File object for stdin input\n        schema_path: Path to the JSON Schema file\n        result: ValidationResult to populate\n        early_exit: If True, stop on first error\n\n    Returns:\n        True if validation passes, False otherwise\n    \"\"\"\n    try:\n        from jsonschema import Draft7Validator, ValidationError as SchemaValidationError\n        from jsonschema.exceptions import SchemaError\n    except ImportError:\n        result.add_error(\n            ValidationError(\n                \"jsonschema library not installed. Install with: pip install jsonschema\"\n            )\n        )\n        return False\n\n    try:\n        with open(schema_path, \"r\", encoding=\"utf-8\") as f:\n            schema = json.load(f)\n    except FileNotFoundError:\n        result.add_error(ValidationError(f\"Schema file not found: {schema_path}\"))\n        return False\n    except json.JSONDecodeError as e:\n        result.add_error(\n            ValidationError(\n                f\"Invalid JSON in schema file: {e.msg}\",\n                line=e.lineno,\n                column=e.colno,\n            )\n        )\n        return False\n\n    try:\n        if file_path:\n            with open(file_path, \"r\", encoding=\"utf-8\") as f:\n                data = json.load(f)\n        elif file_obj:\n            content = file_obj.read()\n            data = json.loads(content)\n        else:\n            result.add_error(ValidationError(\"No input file or stream provided\"))\n            return False\n    except json.JSONDecodeError as e:\n        result.add_error(\n            ValidationError(\n                f\"Invalid JSON syntax: {e.msg}\",\n                line=e.lineno,\n                column=e.colno,\n            )\n        )\n        return False\n\n    try:\n        validator = Draft7Validator(schema)\n    except SchemaError as e:\n        result.add_error(\n            ValidationError(\n                f\"Invalid JSON Schema: {e.message}\",\n                path=\"/\".join(str(p) for p in e.path) if e.path else None,\n            )\n        )\n        return False\n\n    errors = list(validator.iter_errors(data))\n\n    if not errors:\n        return True\n\n    for error in errors:\n        json_path = \"$\"\n        if error.absolute_path:\n            path_parts = [str(p) for p in error.absolute_path]\n            json_path = \"$.\" + \".\".join(path_parts)\n\n        schema_path_str = None\n        if error.schema_path:\n            schema_path_str = \"/\".join(str(p) for p in error.schema_path)\n\n        context = None\n        if error.instance is not None:\n            instance_str = json.dumps(error.instance, default=str)\n            if len(instance_str) > 50:\n                instance_str = instance_str[:47] + \"...\"\n            context = f\"value: {instance_str}\"\n\n        result.add_error(\n            ValidationError(\n                message=error.message,\n                path=json_path,\n                context=context,\n            )\n        )\n\n        if early_exit:\n            break\n\n    return False\n\n\ndef format_output(\n    result: ValidationResult,\n    output_format: str,\n    show_timing: bool,\n    quiet: bool,\n) -> str:\n    \"\"\"Format the validation result for output.\"\"\"\n    if output_format == \"json\":\n        output = result.to_dict()\n        if not show_timing:\n            output.pop(\"elapsed_seconds\", None)\n            output.pop(\"file_size_bytes\", None)\n        return json.dumps(output, indent=2)\n\n    if result.valid:\n        if quiet:\n            return \"\"\n        msg = \"Valid JSON\"\n        if show_timing and result.elapsed_time is not None:\n            msg += f\" (validated in {result.elapsed_time:.4f}s\"\n            if result.file_size:\n                mb = result.file_size / 1_000_000\n                throughput = mb / result.elapsed_time if result.elapsed_time > 0 else 0\n                msg += f\", {mb:.2f}MB, {throughput:.1f}MB/s\"\n            msg += \")\"\n        return msg\n\n    lines = [f\"Validation failed with {len(result.errors)} error(s):\"]\n    for i, error in enumerate(result.errors, 1):\n        lines.append(f\"  {i}. {error.to_text()}\")\n\n    if show_timing and result.elapsed_time is not None:\n        lines.append(f\"\\nTime: {result.elapsed_time:.4f}s\")\n\n    return \"\\n\".join(lines)\n\n\ndef main() -> int:\n    \"\"\"Main entry point.\"\"\"\n    parser = create_parser()\n    args = parser.parse_args()\n\n    result = ValidationResult()\n    start_time = time.perf_counter()\n\n    file_path: str | None = None\n    file_obj: TextIO | None = None\n\n    if args.file == \"-\":\n        file_obj = sys.stdin\n    else:\n        file_path = args.file\n        if not Path(file_path).exists():\n            result.add_error(ValidationError(f\"File not found: {file_path}\"))\n            result.elapsed_time = time.perf_counter() - start_time\n            print(\n                format_output(result, args.output, args.timing, args.quiet),\n                file=sys.stderr,\n            )\n            return 1\n\n    early_exit = not args.full_scan\n    show_progress = not args.no_progress\n\n    syntax_valid = validate_json_syntax_streaming(\n        file_path=file_path,\n        file_obj=file_obj,\n        result=result,\n        early_exit=early_exit,\n        show_progress=show_progress,\n    )\n\n    if syntax_valid and args.schema:\n        if file_path:\n            validate_json_schema(\n                file_path=file_path,\n                file_obj=None,\n                schema_path=args.schema,\n                result=result,\n                early_exit=early_exit,\n            )\n        else:\n            result.add_error(\n                ValidationError(\n                    \"Schema validation with stdin requires reading input twice. \"\n                    \"Please provide a file path instead of stdin when using --schema.\"\n                )\n            )\n\n    result.elapsed_time = time.perf_counter() - start_time\n\n    output = format_output(result, args.output, args.timing, args.quiet)\n    if output:\n        if result.valid:\n            print(output)\n        else:\n            print(output, file=sys.stderr)\n\n    return 0 if result.valid else 1\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n"
